fn parse_selections(packages: &[String]) -> Result<Vec<ReleasePackageId>, CliError> {
    packages.iter().map(|raw| parse_release_selection(raw)).collect()
}

/// Parses one `--package` release selection: `eco/name` only, the same grammar as the release decision file.
fn parse_release_selection(raw: &str) -> Result<ReleasePackageId, CliError> {
    callisto_graph::ConfigError::reject_colon_form(raw, "--package").map_err(callisto_graph::GraphError::Config)?;
    match PackageId::parse(raw) {
        Ok(PackageId::Prefixed { ecosystem, name }) => {
            ReleasePackageId::new(ecosystem, name).map_err(|error| CliError::ReleasePackageInvalid {
                raw: raw.to_string(),
                detail: error.to_string(),
            })
        }
        _ => Err(CliError::ReleasePackageInvalid {
            raw: raw.to_string(),
            detail: "expected an ecosystem-qualified package id, e.g. `cargo/pkg`".to_string(),
        }),
    }
}

/// One-line description of a release operation, shared by both the plain and table renderers.
fn describe_operation(operation: &callisto_model::ReleaseOperation) -> String {
    match &operation.id().role {
        callisto_model::ReleaseOperationRole::RegistryPublish { registry } => {
            format!("publish to {}", registry.registry_key().display_name())
        }
        callisto_model::ReleaseOperationRole::PlatformPublish { registry, platform } => {
            format!(
                "publish {} to {}",
                platform.name(),
                registry.registry_key().display_name()
            )
        }
        callisto_model::ReleaseOperationRole::Tag => "create git tag".to_owned(),
        callisto_model::ReleaseOperationRole::ForgeRelease => "create GitHub release draft".to_owned(),
        callisto_model::ReleaseOperationRole::ArtifactUpload { slot } => {
            format!("upload {}", slot.asset_name)
        }
        callisto_model::ReleaseOperationRole::ForgePublish => "publish GitHub release".to_owned(),
    }
}

